import importlib
import inspect
import sys
import tkinter as tk
from tkinter import ttk

from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg, NavigationToolbar2Tk
from matplotlib.figure import Figure

from mpldemo import EXAMPLES


class Demo:
    def __init__(self, first=0):
        self.root = root = tk.Tk()
        root.title("matplotlib: примеры")
        top = tk.Frame(root)
        top.pack(side="top", fill="x")
        self.pick = ttk.Combobox(top, state="readonly", values=[title for name, title in EXAMPLES])
        self.pick.pack(side="left", fill="x", expand=True, padx=4, pady=4)
        self.pick.bind("<<ComboboxSelected>>", lambda e: self.show(self.pick.current()))
        tk.Button(top, text="Код", command=self.code).pack(side="left", padx=(0, 4))
        self.fig = Figure(figsize=(5.6, 4.2), dpi=100)
        self.canvas = FigureCanvasTkAgg(self.fig, master=root)
        NavigationToolbar2Tk(self.canvas, root)
        self.canvas.get_tk_widget().pack(side="top", fill="both", expand=True)
        self.keep = None
        self.module = None
        self.pick.current(first)
        self.show(first)

    def show(self, i):
        if self.keep is not None and getattr(self.keep, "event_source", None):
            self.keep.event_source.stop()
        self.fig.clear()
        self.module = importlib.import_module("mpldemo." + EXAMPLES[i][0])
        self.keep = self.module.draw(self.fig)
        self.canvas.draw_idle()

    def code(self):
        win = tk.Toplevel(self.root)
        win.title(self.module.__name__)
        win.transient(self.root)
        text = tk.Text(win, width=72, height=24, wrap="none")
        text.insert("1.0", inspect.getsource(self.module))
        text.config(state="disabled")
        text.pack(fill="both", expand=True)


def main():
    names = [name for name, title in EXAMPLES]
    arg = sys.argv[1] if len(sys.argv) > 1 else names[0]
    if arg not in names:
        sys.exit("mpldemo: нет примера %s, есть: %s" % (arg, " ".join(names)))
    Demo(names.index(arg)).root.mainloop()


if __name__ == "__main__":
    main()
